def esc(x): return html.escape(x,quote=True)
def block(id,label,txt):
 return f'<div class="guide-code"><div class="guide-code-head"><span>{esc(label)}</span><button class="small" data-copy-target="{id}">Kopyala</button></div><pre id="{id}">{esc(txt)}</pre></div>'
def call(label,body,kind='ok'): return f'<div class="guide-call {kind}"><strong>{label}</strong><div>{body}</div></div>'
def jump(i,label): return f'<button class="small" data-guide="{i}">{label} →</button>'
def source(file,label): return f'<a href="https://github.com/Fission-AI/OpenSpec/blob/main/docs/{file}" target="_blank" rel="noopener">{label} ↗</a>'
def panel(title,body): return f'<details class="guide-details"><summary>{title}</summary><div>{body}</div></details>'
guide=[]
def add(title,sub,body,out,refs=''):
 guide.append(dict(title=title,sub=sub,body=body,out=out,refs=refs))
add('Bir dosya. Baştan sona bir rota.','Sunum öğretir; bu rehber bilgisayarında işi yaptırır.', '''<div class="guide-map"><div><b>01</b><strong>Çalışan ortam</strong><span>Terminal → CLI → doğru proje</span></div><div><b>02</b><strong>Kaynaklı bağlam</strong><span>Mobil + API + backend + karar</span></div><div><b>03</b><strong>İncelenmiş plan</strong><span>Proposal → spec → design → tasks</span></div><div><b>04</b><strong>Kanıtlı kapanış</strong><span>Uygula → sına → sync → archive</span></div></div>
<p>Önce rehber panelinden işletim sistemini ve asistanını seç. Soldaki adımları sırayla tamamla. Her adımın sonunda <b>“Geçiş kanıtı”</b> var: yalnız okumuş olmak yeterli değil.</p><div class="guide-grid"><div><h3>Bu eğitimle çıkaracağın iş</h3><p>Kendi ürününde tek akış için kaynak sicili, açık kararlar, bir değişiklik planı ve kabul kanıtı. Kod yazmak PM’in ön koşulu değil; uygulama ve test aşamasını mühendislikle yürütürsün.</p></div><div><h3>Yanında bulunacak malzeme</h3><p>Bilgisayar ve terminal, Node/npm, erişimi olan bir AI kod asistanı, ürünün kaynakları ve karar sahipleri. Kurulum için internet; bu rehberi okumak için internet gerekmez.</p></div></div>
<p><b>OpenSpec ne yapar?</b> Asistana ortak bir çalışma yöntemi ve dosya düzeni verir. Beklenen davranış ile önerilen değişikliği sürümlenen metinlerde tutar. AI hesabı, ürün bilgisi, kod erişimi, test ortamı ve release otomatik oluşmaz.</p>
<div class="guide-legend"><span>TERMINAL = komut çalıştır</span><span>ASİSTAN SOHBETİ = mesaj gönder</span><span>DOSYA = oku / düzenle</span><span>EKİP = kararı incele</span></div>
<p>Bu rehber PM’in ilk işi ve günlük kullanımı içindir. İleri seçenekler atlas içinde. Kaynak linkleri doğrulama içindir; gerekli açıklamalar bu dosyada bulunur.</p>''','Hangi projede, hangi asistanla, hangi tek kullanıcı sonucunu ele alacağını bir cümleyle yaz.',source('how-commands-work.md','Terminal ve sohbet ayrımı'))
add('Önce komutları çalıştıran ortam.','Node, npm ve terminal: üç adı ezberlemek yerine işlerini bil.', '''<div class="guide-grid"><div><h3>Terminali aç</h3><p><b>macOS:</b> ⌘ Space → Terminal → Enter.<br><b>Windows:</b> Başlat → PowerShell veya Windows Terminal.<br><b>Linux:</b> uygulama menüsü → Terminal.</p><p>Bir komutu yapıştırıp Enter’a bas. Sonuç gelmeden sonraki satıra geçme. Başındaki <code>$</code> terminal işaretiyse yazılmaz; <code>$openspec-…</code> ise Codex sohbetindeki skill adının parçasıdır.</p></div><div><h3>Node ve npm</h3><p><b>Node</b>, OpenSpec’in çalıştığı JavaScript ortamı. <b>npm</b>, OpenSpec paketini indirip kuran araç. OpenSpec için Node <b>20.19.0 veya daha yeni</b> gerekir; desteklenen LTS kullan.</p></div></div>'''+block('g-runtime','TERMINAL · her klasörde çalışabilir','node --version\nnpm --version')+call('Beklenen sonuç','Node için <code>v…</code>, npm için bir sürüm numarası. Örneğin Node <code>v22.x</code> asgari koşulu geçer; <code>v20.18</code> geçmez.')+panel('Node yoksa nasıl kurarım?', '''<ol><li><a href="https://nodejs.org/en/download" target="_blank" rel="noopener">Resmi Node indirme sayfasını</a> aç; LTS sürümünü ve işletim sistemini seç.</li><li>macOS için Installer/.pkg, Windows için Installer/.msi indir. Cihaz mimarini seç: Mac → Bu Mac Hakkında, Windows → Ayarlar → Sistem → Hakkında. Kurucuyu aç, adımları tamamla; npm bileşenini dahil et.</li><li>Terminali kapatıp yeni terminal aç. İki sürüm komutunu tekrar çalıştır.</li><li>Linux veya ekipçe yönetilen bilgisayarda mevcut Node yöneticisini/kurulum yöntemini koru. Sürüm eskiyse o yöntemle desteklenen LTS’ye geç; kurum kurulum yetkisi gerekiyorsa BT’den Node+npm iste.</li></ol><p>nvm/fnm/asdf/Volta zaten varsa ikinci bir yöntem kurma. Aktif Node sürümü değişince global CLI’ın görünürlüğünü yeniden kontrol et.</p>''')+call('Asistan da hazır olmalı','Halihazırda kullandığın Codex / Claude Code / Cursor hesabında oturum aç. Uygulamada bir yerel proje açıp basit bir dosyayı okuyabildiğini doğrula. Sıradan web sohbetine repo URL’si yapıştırmak yerel dosya erişimi sağlamaz.','note')+panel('AI kod asistanım henüz yok', '''<p>Bu eğitimin varsayılanı Codex. <a href="https://chatgpt.com/codex" target="_blank" rel="noopener">Resmi Codex girişinden</a> masaüstü uygulamasını indir, kur, oturum aç ve yerel klasörünü proje olarak aç. Kurum hesabında izin verilen asistanı kullan. Claude Code veya Cursor zaten varsa üstte onu seç; komutlar ona uyarlanır.</p><p>CLI tercih eden macOS/Linux kullanıcıları için resmi Codex kurucusu ve ilk açılış:</p>'''+block('g-codex-install','TERMINAL · isteğe bağlı Codex CLI','curl -fsSL https://chatgpt.com/codex/install.sh | sh\ncodex')+'''<p>İlk açılışta sunulan giriş seçeneğiyle hesabına gir. OpenSpec kurulumu bu asistan kurulumundan ayrıdır.</p>'''),'Node/npm sürümleri koşulu geçiyor ve seçilen asistan hesabı bir yerel dosyayı okuyabiliyor.',source('installation.md','Runtime ve kurulum')+' · <a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noopener">Codex kurulum kaynağı ↗</a>')
add('Kullanıcı hesabına CLI kur.','Global, “bütün ürünlerin bağlamı ortak” demek değil; komutun her klasörden çağrılabilmesi demek.', '''<p>Aşağıdaki komutlar seçtiğin işletim sistemine göre değişir. Mevcut Node yöneticin çalışıyorsa <b>standart kurulumu</b> seç. İzin hatasında home alternatifi kendi kullanıcı klasörüne kurar; sistem dizinine yazmaz.</p><h3>Standart kurulum</h3><div data-install-standard></div><h3>Home alternatifi</h3><div data-install-home></div><div data-path-help></div>
<div class="guide-grid"><div><h3>Kurulum dizini ≠ kişisel ayar</h3>'''+block('g-prefix','TERMINAL · yer gösterir, kurulumu başlatmaz','npm prefix -g\nopenspec config path')+'''<p><code>npm prefix -g</code> npm’in varsayılan global hedefini gösterir. Tek komutta kullanılan <code>--prefix</code> bu varsayılanı değiştirmez. <code>openspec config path</code> kullanıcıya ait ayar dosyasının konumunu gösterir.</p></div><div><h3>PATH ne?</h3><p>Terminalin çalıştırılabilir program aradığı dizin listesi. Home kurulumunda komut dosyası bu listeye eklenir. <code>export</code> yalnız mevcut terminal içindir; kalıcı eklemeyi sağdaki/aşağıdaki açıklamaya göre yap.</p><p>Ürün bağlamı daha sonra <code>proje/openspec/config.yaml</code> içinde tutulur. CLI’ı home’a kurmak bütün ürünlerin planını home’da tutmayı gerektirmez.</p></div></div>'''+jump(12,'Komut bulunamadı / izin / ağ hatası'),'Yeni açılmış terminalde openspec --version ve openspec --help çalışıyor.',source('installation.md','Kurulum')+' · '+source('cli.md','Config ve CLI'))
add('Dosyaların yazılacağı kökü seç.','Root = bu işin ana klasörü. Mobil ve backend ayrıysa bunu açıkça seç.', '''<div class="guide-map three"><div><b>A</b><strong>Tek repo</strong><span>Mobil ve backend aynı repo’da: mevcut repo kökü.</span></div><div><b>B</b><strong>Ayrı repolar</strong><span>PM için planlama repo’su; mobil/backend ayrıca erişilebilir.</span></div><div><b>C</b><strong>Kod erişimi yok</strong><span>Planlama klasörü + API/ekran/kural/test çıktısı. Görülmeyen kod “bilinmiyor”.</span></div></div>
<p><b>Mevcut ekip düzeni varsa onu kullan.</b> Yeni PM pilotunda ayrı planlama klasörü basit bir başlangıçtır. Klasör adları örnektir; gerçek yollarını yaz. Ürün A ve ürün B aynı root’ta karışmasın.</p><div data-root-commands></div><p><code>pwd</code> veya <code>Get-Location</code> çıktısı, komutun hangi klasörde çalıştığını gösterir. Bu adımdan sonraki <code>openspec</code> komutları bu kökte çalışır. Home (<code>~</code>) ürün kökü değildir.</p>
'''+panel('Git / repo / clone ilk kez duyuyorum', '''<p><b>Repo</b>, dosyaların sürüm geçmişiyle tutulduğu proje. <b>Clone</b>, uzaktaki repo’nun bilgisayarında çalışma kopyasını oluşturur. <b>Branch</b>, aynı repo içinde ayrı çalışma hattı. <b>Commit</b>, belirli bir kayıtlı sürümü tanımlar.</p><ol><li><code>git --version</code> çalıştır. Mac’te eksikse komutun önerdiği geliştirici araçlarını kur. Windows’ta <a href="https://git-scm.com/install/windows" target="_blank" rel="noopener">resmi Git kurucusunu</a> kullan. Yönetilen cihazda BT yöntemini izle.</li><li>Ekipten repo URL’sini, erişim yetkisini ve incelenecek branch’i al. URL tek başına izin vermez.</li><li>Asistandan aşağıdaki mesajla klonlama ve kaynak sürüm kaydı iste. Erişim reddedilirse repo sahibinden yetki al; erişemediğini “incelendi” sayma.</li></ol>'''+block('g-clone','ASİSTAN SOHBETİ · yolları ve URL’leri doldur','Planlama root: <mutlak yol>.\nMobil repo URL: <URL>; checkout hedefi: <mutlak yol>; branch: <branch>.\nBackend repo URL: <URL>; checkout hedefi: <mutlak yol>; branch: <branch>.\nMevcut checkout varsa onu kullan; değişikliklerini koru, reset yapma.\nYoksa erişimi doğrulayıp belirtilen yere clone et.\nHer repo için branch, HEAD commit ve çalışma kopyasındaki değişiklikleri raporla.\nUygulama kodunu değiştirme. Başaramadığın repo’yu açıkça belirt.'))+'''<h3>Asistana klasörleri gerçekten ver</h3><p>Yerel proje ayarlarında planlama klasörünü ana/primary klasör yap. Mobil ve backend’i ek klasör olarak ekle veya kullandığın IDE’nin workspace’inde aç. Bu klasörler erişim kapsamına girer; mesajda keşif sırasında kod değişikliği istemediğini belirt. Her kaynağın okunabildiğini bir sonraki adımda kanıtlat.</p>
<p>CLI kullanıyorsan önce planlama köküne geçip asistanını başlat. Başka bir root’ta açık sohbet, terminalde <code>cd</code> yaptın diye otomatik taşınmış sayılmaz.</p>''','Planlama, mobil ve backend yolları; branch/commit; erişilemeyen kaynaklar tek kayıtta görünüyor.',source('existing-projects.md','Mevcut proje')+' · <a href="https://learn.chatgpt.com/docs/projects" target="_blank" rel="noopener">Yerel proje erişimi ↗</a>')
add('Bu projeye OpenSpec’i bağla.','CLI kurulu. Şimdi asistanın bu root’ta OpenSpec yöntemini bulmasını sağla.', '''<div data-init-commands></div><p>Terminaldeki <code>init</code>, projeye OpenSpec düzenini ve seçtiğin asistanın yönerge dosyalarını ekler. Uygulama kodunu üretmez. Özel bir OpenSpec sohbet ekranı açmaz.</p><div class="guide-grid"><div><h3>Dosya kontrolü</h3><p>Proje ağacında <code>openspec/</code> ve asistan için üretilen skill/komut dosyalarını gör. <code>config.yaml</code> bağlam özelleştirmesi içindir; ana <code>specs/</code> başlangıçta boş olabilir.</p><div data-skill-path></div></div><div><h3>Sohbet kontrolü</h3><p>Asistanı aynı proje kökünde yeniden aç veya skill listesini yeniden yükle. Aşağıdaki keşif çağrısını <b>sohbete</b> gönder; terminale değil.</p><div data-explore-check></div></div></div>
'''+call('Başarı nasıl görünür?','Asistan doğru root’u ve aktif OpenSpec change’lerini (henüz yoksa yok) söyler. İlgili skill’i kullanır; <code>openspec: command not found</code> veya genel yöntem açıklamasıyla yetinmez.')+panel('User altında skill de olsun istiyorum', '''<p>İlk kullanım için proje skill’i yeterli. CLI global; ürün verisi proje özelinde kalır. Codex’te kişisel skill keşif yolu <code>~/.agents/skills</code>. OpenSpec’i bir kişisel toolkit klasöründe init edip üretilen skill’leri buraya symlink etmek manuel bir seçenektir; ayrı bir <code>init --global</code> komutu varsayma.</p><p>Skill’ler yöntemi taşır, ürün A’nın domain bağlamını ürün B’ye taşımaz. Proje skill’i ile aynı adlı kişisel kopyayı bakım yapmadan çoğaltma. Tam kişisel kurulum reçetesi bu dosyanın atlasında:</p><button class="small" data-atlas-jump="9">Kişisel skill reçetesini aç →</button>''')+panel('Başka bir asistan / eski sürüm?', '''<p><code>openspec init --help</code> ile kurulu CLI’ın desteklediği tool ID’lerini gör. Üretilen dosyalar ve init çıktısı esas. Üstteki seçim Codex, Claude Code ve Cursor için uyarlanır. Claude Code ile sıradan Claude web sohbeti aynı ortam değildir.</p><p>Varsayılan <b>core</b> yolunu kullan: explore / propose / apply / update / sync / archive. Expanded yol (new / continue / ff / verify / onboard vb.) için terminalde <code>openspec config profile</code>, ardından bu root’ta <code>openspec update</code>. Bu, asistan yönergelerini yeniler. İlk işi başlatmak için expanded gerekmez.</p>'''),'Doğru root’ta üretilen skill görülüyor ve keşif çağrısı başarıyla çalışıyor.',source('supported-tools.md','Asistan yolları')+' · '+source('how-commands-work.md','Komut çalışma biçimi'))
add('En güçlü bağlamı kaynaklardan çıkar.','Ürün niyeti + ilgili kanıt + sürüm + açık karar. Bütün repo’yu sohbete dökmek bu dördünü sağlamaz.', '''<div class="guide-grid"><div><h3>PM’in vereceği</h3><p>Kullanıcı/segment, sorun, beklenen sonuç, kapsam dışı, bilinen iş kuralları ve sahipleri. Ölçüm varsa olayın tanımı ve başlangıç verisi; yoksa “ölçülmedi”. Domain = ürünün problem/iş kuralı alanı.</p></div><div><h3>AI’ın çıkaracağı</h3><p>Tek akışın ekran → istek → API → backend handler → domain kuralı → veri/olay → test rotası. Dosya ve sembolleri varsaymadan keşfeder. Kaynağın sürümünü belirtir.</p></div></div><div data-audit-prompt></div>
<table class="guide-table"><thead><tr><th>Bilgi türü</th><th>Örnek</th><th>Nasıl kullanılır?</th></tr></thead><tbody><tr><td>Gözlem</td><td>Mobil timeout’ta hata gösteriyor.</td><td>Dosya/sembol + commit. Doğru ürün davranışı olduğuna tek başına karar vermez.</td></tr><tr><td>Onaylı kural</td><td>Doğrulanmayan sonucu başarısız göstermeyiz.</td><td>Karar kaydı + sahibi + tarih.</td></tr><tr><td>Varsayım</td><td>Talep 24 saatte uygulanır.</td><td>Kaynak yoksa onaylı kural gibi spec’e girmez.</td></tr><tr><td>Bilinmeyen</td><td>Canlı ortamda flag açık mı?</td><td>İlgili release/operasyon sahibine soru.</td></tr><tr><td>Çelişki</td><td>Doküman “anlık”, kod “beklemede”.</td><td>İki kaynağı da göster; beklenen davranışı sahibi seçer.</td></tr></tbody></table>
'''+panel('Kod repolarına erişemiyorsam?', '''<p>Ekran kaydı, API/OpenAPI çıktısı, akış belgesi, iş kuralı, anonimleştirilmiş destek örneği ve mevcut test/kabul kayıtlarıyla başlayabilirsin. Her belgenin tarih/sürümünü yaz. AI’a <b>“Bu paket implementasyonu kanıtlamaz; koddan doğrulanacakları ayrı listele”</b> de. Önce kullanıcı davranışının planını yaz; mühendislik teknik uygulanabilirlik ve kod eşlemesini tamamlasın.</p>''')+call('Genel cevap geldiyse','“Bu iddiayı hangi dosyada, hangi sembolde gördün? Okuduğun ilgili bölümü ve sürümü göster. Erişmediğin kaynağı bulgu sayma.” diye geri çevir. Dosya yolunu görmek dosyayı okumak değildir.','note'),'En az bir akış iki taraf boyunca izleniyor; her iddia kaynaklı; okunamayanlar ve karar sahipleri ayrılmış.',source('explore.md','Keşif')+' · '+source('existing-projects.md','Mevcut sistem'))
add('Bağlamı kalıcı bir pakete dönüştür.','Konuşmada kalan bilgi bir sonraki PM’in veya yeni sohbetin başlangıcı olamaz.', '''<p>Bu dizin yapısı <b>eğitim önerisi</b>; resmi zorunlu OpenSpec yapısı değildir. AI’ın ilk taslağını PM/domain sahibi/mühendislikle kontrol et, sonra planlama repo’sunda sürümle.</p>'''+block('g-context-tree','DOSYA DÜZENİ · planlama root’unda','docs/context/README.md   → okuma rotası, domain, sahip\ndocs/context/sources.md  → repo/belge, sürüm, durum\ndocs/context/domain.md   → terimler, onaylı kurallar\ndocs/context/flow.md     → akış, hata yolları, açık kararlar\nopenspec/config.yaml    → kısa bağlam + belge kuralları\nAGENTS.md               → asistanın okuma protokolü')+'''<div class="guide-grid"><div><h3>Küçük giriş, derin kanıt</h3><p><code>config.yaml</code> bütün repo’nun dump’ı değil. Ürünü ve okuma rotasını kısa anlatır; ilgili dosyaların gerçekten okunmasını ister. <code>context</code> bütün artifact yönergelerine eklenir. <code>rules</code> yalnız ilgili belge türüne yön verir.</p><p>Generated skill’lerin içine ürün bilgisi yazma; tool güncellemesi onları yenileyebilir. Domain bilgisi kendi sürümlenen dosyalarında yaşasın.</p></div><div><h3>Bakım anlaşması</h3><p>Her ortak kuralın sahibi olsun. Aynı kural her PM’e ayrı kopya verilmesin. Sözleşme, flag, ürün kararı veya ilgili kod değiştiğinde kaynak kaydını güncelle. Yeni işte bütün paketi körü körüne okumak yerine ilgili akışı seç.</p></div></div>'''+block('g-persist','ASİSTAN SOHBETİ · review edilmiş bulgulardan dosya üret','İncelenen bulguları docs/context/ dosyalarına kaynaklarıyla kaydet.\nREADME: ürün, sahipler ve iş türüne göre okuma rotası.\nsources: repo/branch/commit, belge sürümü, canlı ortam durumu.\ndomain: sözlük ve onaylı kurallar. flow: akış, hatalar, kararlar/sahipler.\nopenspec/config.yaml varsa mevcut schema/context/rules ile birleştir.\nYoksa spec-driven schema ile kısa context ve artifact rules öner.\nAGENTS.md varsa mevcut talimatları koru; bağlam okuma protokolünü ekle.\nPath’in içeriğinin otomatik yüklendiğini varsayma; ilgili dosyaları oku.\nŞablon yer tutucularını gerçek bulguyla değiştir. Kod değiştirme.')+'''<p>Tüm şablonların içeriği atlas içinde okunabilir ve kopyalanabilir. ZIP de HTML’e gömülü; yan dosya gerekmez.</p><button class="small" data-atlas-jump="11">Config + context şablonlarını aç →</button><button class="small" data-kit-download>Başlangıç paketini indir ↓</button>''','Yeni sohbette README’den başlayınca aynı akış ve aynı karar kaynakları yeniden bulunabiliyor.',source('customization.md','Context, rules ve schema'))
add('İlk işi küçült; ürün kararlarını koy.','“Paket değişikliğini düzelt” yerine tek bir gözlemlenebilir sonucu seç.', '''<div class="guide-map three"><div><b>NİYET</b><strong>Ne iyileşecek?</strong><span>Yanıt kaybında kullanıcı yanlışlıkla başarısızlık görmesin.</span></div><div><b>SINIR</b><strong>Neler dışarıda?</strong><span>Fiyat/uygunluk politikası, kampanya, geçmiş talep ekranı.</span></div><div><b>KABUL</b><strong>Ne gözleyeceğiz?</strong><span>Aynı niyet ikinci talep yaratmıyor; doğrulanmış durum gösteriliyor.</span></div></div>
<p><b>Örnek ürün kararları:</b> doğrulanmayan sonuç belirsiz gösterilir; kabul edilme ile uygulanma ayrılır; aynı kullanıcı niyeti tekrar gönderilince ikinci talep yaratılmaz. Bunlar bu eğitimin kurallarıdır, senin ürününe otomatik taşınmaz.</p><p><b>Karar henüz yoksa:</b> soruyu, seçenekleri, etkisini ve karar sahibini yaz. İşin davranışını değiştiren karar açıkken AI’ın seçimiyle “hazır” demeyin. Teknik yaklaşımı mühendislik, kritik senaryoları QA ile inceleyin.</p><div data-propose-prompt></div>
'''+call('Beklenen dosyalar','<code>openspec/changes/recover-package-change-result/</code> altında proposal.md, specs/package-change/spec.md, design.md ve tasks.md. Bu dört belge varsayılan spec-driven schema içindir; özel şema farklı olabilir.')+'''<p>Proposal neden/ne/kapsam, spec beklenen davranış, design teknik yaklaşım, tasks uygulama ve doğrulama işleri. Dört belgenin aynı değişikliği anlattığını kontrol et.</p>'''+jump(8,'Tam örnek dosyaları incele'),'Bir değişiklik kimliği, net kapsam, karar sahipleri ve senaryoları içeren dört tutarlı belge var.',source('reviewing-changes.md','İnceleme')+' · '+source('concepts.md','Belge rolleri'))
case={}
case['openspec/specs/package-change/spec.md']='''# Package Change

## Purpose
Paket değişikliği sonucunu kullanıcıya doğru durumla göstermek.
Bu başlangıç davranışı eğitim örneğidir, gerçek repo bulgusu değildir.

## Requirements

### Requirement: Gönderim sonucu
Sistem başarılı kabul yanıtında talebin alındığını göstermelidir (MUST).
Yanıt alınamazsa sistem genel hata göstermelidir (MUST).

#### Scenario: Kabul yanıtı alınır
- GIVEN kullanıcı uygun bir paket değişikliği gönderdi
- WHEN backend talebi kabul etti ve yanıt cihaza ulaştı
- THEN kullanıcı "Talebiniz alındı" görür

#### Scenario: Yanıt alınamaz
- GIVEN kullanıcı paket değişikliği gönderdi
- WHEN cihaz yanıt alamaz
- THEN kullanıcı genel hata görür
'''
case['openspec/changes/recover-package-change-result/proposal.md']='''## Why
Eğitim vakasında backend talebi kabul etse de yanıt kaybolabiliyor.
Genel hata kullanıcıyı aynı niyeti yeniden göndermeye yöneltiyor.
Beklenen sonuç: belirsizliği doğru gösterip ikinci talebi önlemek.

## What Changes
- Doğrulanamayan sonucu belirsiz göster; kesin ret olarak etiketleme.
- Kabul edilen ve uygulanması doğrulanmış talebi ayrı göster.
- Aynı niyetin tekrarını aynı talebe bağla.
- İlgili ekrana dönüşte doğrulanmamış talebi toparla.
- Kesin ret gerekçesini ve uygun devam yolunu göster.
Kapsam dışı: fiyat/fatura, uygunluk politikası, kampanya,
geçmiş talep ekranı ve yeni bildirim kanalı.

## Capabilities
### New Capabilities
- Yok.
### Modified Capabilities
- package-change: sonuç gösterimi, aynı niyet ve toparlanma davranışı.

## Impact
Mobil gönderim ve dönüş akışı; backend talep eşleme ve durum sorgusu;
API sözleşmesi; eski mobil sürüm uyumu; ilgili testler ve ölçüm.
Ürün kararları: bu eğitim için kararlaştırılmış örnek kurallar.
Gerçek işte kaynak/sürüm, karar sahipleri ve hedef ölçüm eklenir.
'''
case['openspec/changes/recover-package-change-result/specs/package-change/spec.md']='''## MODIFIED Requirements

### Requirement: Gönderim sonucu
Sistem yalnız doğrulanmış talep durumunu sonuç olarak göstermelidir (MUST).
Kabul edilmiş talebi "Talebiniz alındı", uygulanması doğrulanmış talebi
"Paketiniz uygulandı", doğrulanamayan sonucu "Sonuç kontrol ediliyor"
olarak göstermelidir (MUST). Kesin rette gerekçeyi ve uygun devam yolunu
sunmalıdır (MUST). Yanıt kaybı tek başına kesin ret değildir.

#### Scenario: Kabul yanıtı alınır
- GIVEN kullanıcı uygun paket değişikliği gönderdi
- WHEN backend talebi kabul etti ve yanıt cihaza ulaştı
- THEN "Talebiniz alındı" gösterilir
- AND paket uygulanmış gibi gösterilmez

#### Scenario: Yanıt alınamaz
- GIVEN talep gönderildi
- WHEN cihaz yanıt alamaz ve durum sorgusu da sonuç vermez
- THEN "Sonuç kontrol ediliyor" gösterilir
- AND kesin başarısızlık veya uygulanma gösterilmez

#### Scenario: Uygulanma doğrulanır
- GIVEN gönderilmiş bir talep var
- WHEN yetkili durum kaynağı uygulanmayı doğrular
- THEN "Paketiniz uygulandı" gösterilir

#### Scenario: Kesin ret doğrulanır
- GIVEN talep uygunluk nedeniyle kesin reddedildi
- WHEN yetkili durum kaynağı reti doğrular
- THEN uygunluk gerekçesi gösterilir
- AND kullanıcı paket seçimine geri dönebilir
- AND otomatik yeniden gönderim yapılmaz

## ADDED Requirements

### Requirement: Aynı niyetin tekrar gönderimi
Sistem aynı kullanıcı niyetinin tekrarında ikinci paket değişikliği
oluşturmamalıdır (MUST). Kullanıcının farklı yeni niyeti bağımsız
bir talep olarak ele alınmalıdır (MUST).

#### Scenario: Aynı niyet tekrar gönderilir
- GIVEN ilk gönderimin sonucu bilinmiyor
- WHEN aynı kullanıcı aynı niyeti tekrar gönderir
- THEN aynı talebin güncel durumu döndürülür
- AND ikinci talep oluşturulmaz

#### Scenario: Eşzamanlı tekrar
- GIVEN aynı niyetle eşzamanlı iki gönderim yapılır
- WHEN backend bu gönderimleri işler
- THEN en fazla bir talep kaydı oluşur
- AND iki yanıt aynı talebe bağlanır

#### Scenario: Yeni niyet
- GIVEN önceki talebin sonucu doğrulandı
- WHEN kullanıcı farklı bir paket seçip yeni değişikliği onaylar
- THEN bu niyet bağımsız talep olarak işlenir

### Requirement: Ekrana dönüşte toparlanma
Sistem ilgili ekrana dönen kullanıcı için önceki doğrulanmamış talebin
durumunu sorgulamalıdır (MUST). Durum yine doğrulanamazsa belirsiz
gösterimi korumalıdır (MUST).

#### Scenario: Uygulama yeniden açılır
- GIVEN talep gönderildikten sonra yanıt alınmadan uygulama kapandı
- WHEN aynı kullanıcı uygulamayı açıp paket değişikliği ekranına döner
- THEN önceki talebin durumu sorgulanır
- AND doğrulanırsa o sonuç gösterilir

#### Scenario: Dönüşte durum kaynağına erişilemez
- GIVEN önceki talebin sonucu doğrulanmadı
- WHEN kullanıcı döner fakat durum sorgusu sonuç vermez
- THEN "Sonuç kontrol ediliyor" korunur
- AND bu niyet için ikinci talep oluşturulmaz
'''
case['openspec/changes/recover-package-change-result/design.md']='''## Context
Temsili vakada istemci yanıt alamasa da sunucu kabul etmiş olabilir.
Bu eğitim taslağı bir çözüm yönü önerir; gerçek repo incelenmedi.
Ürün kabulü: delta spec. Uygulamaya geçiş için aşağıdaki açık teknik
kararlar mühendislikle tamamlanmalı.

## Goals / Non-Goals
Goals: aynı niyeti korumak, doğru durum göstermek, ekrana dönüşü toparlamak.
Non-Goals: fiyat/uygunluk politikasını değiştirmek, yeni geçmiş ekranı.

## Decisions (proposed; engineering review required)
- operationKey gönderimden önce istemcide oluşur, aynı niyette korunur.
  Yalnız yanıt içinde dönen requestId yeterli değil: yanıt kaybolabilir.
- Backend (authenticated user, operationKey) eşlemesini atomik tutar.
  Aynı key ve aynı payload aynı talebe bağlanır; farklı payload çelişki
  olarak ele alınır. Kesin davranış API sözleşmesinde netleşir.
- Yetkili durum sorgusu kabul / uygulanma / ret durumlarını ayırır.
- İstemci talep bağını kapanma/dönüş boyunca korur; hesap değişiminde
  başka kullanıcının talebini göstermez.

## Risks / Trade-offs
Eşzamanlı çift gönderim; key saklama süresi; eski istemci; geç gelen
sonuç; yetki sınırı; servis kesintisi; ölçümde aynı niyetin iki sayılması.

## Migration / Rollout
Backend uyumunu önce hazırla; eski mobil istemcileri ayrı doğrula.
Mobil sürüm/flag ve geri dönüş koşulunu ekipçe kararlaştır.
Sync/archive release yapmaz.

## Open Questions (block apply)
- Atomik eşlemenin mevcut altyapıdaki yöntemi ve testi nedir? Backend sahibi.
- Key saklama süresi / bitişte güvenli devam yolu nedir? PM + backend.
- Eski istemci ve payload uyumsuzluğu nasıl davranır? API + mobil sahipleri.
- Ret sözleşmesi, terminal durumlar ve yetki sınırı nedir? Domain + API.
- Hangi test ortamı, rollout/rollback ve gözlem koşulları? QA + release.
'''
case['openspec/changes/recover-package-change-result/tasks.md']='''## 1. Karar ve sözleşme
- [ ] 1.1 Design açık sorularını sahipleriyle çöz; spec ile hizala.
- [ ] 1.2 API durum/payload/ret/yetki sözleşmesini sürümle.
- [ ] 1.3 Eski istemci uyumu ve release/rollback sırasını kararlaştır.

## 2. Backend (yalnız kararlar tamamlandıktan sonra)
- [ ] 2.1 Aynı niyet eşlemesini atomik uygula; yeni niyeti ayrı tut.
- [ ] 2.2 Yetkili durum sorgusunu ve payload çelişkisini uygula.
- [ ] 2.3 Tekrar/eşzamanlılık/yetki testlerini çalıştır, kanıt kaydet.

## 3. Mobil
- [ ] 3.1 Niyet anahtarını ilk gönderimden önce üret ve dönüşte koru.
- [ ] 3.2 Belirsiz / alındı / uygulandı / ret gösterimlerini ayır.
- [ ] 3.3 Dönüş, hesap değişimi ve erişilemeyen durum senaryolarını doğrula.

## 4. Kabul ve kapanış
- [ ] 4.1 Tüm delta senaryolarını ortam/sürüm/test bağlantısıyla kaydet.
- [ ] 4.2 Başarısız ve çalıştırılmamış senaryoları görünür tut; PM/QA review.
- [ ] 4.3 Deltayı sync et; ana spec'i incele; tamamlanan işi archive et.
- [ ] 4.4 Gerçek release ve gözlem kaydını ayrı yürüt.
'''
body='''<p><b>Tek kimlik:</b> <code>recover-package-change-result</code>. <b>Tek capability:</b> <code>package-change</code>. Önce başlangıç spec’i, sonra ona göre MODIFIED/ADDED delta. Böylece “hangi mevcut gereksinimi değiştiriyoruz?” sorusu cevapsız kalmaz.</p>'''+call('Bu örneğin durumu: PLAN TASLAĞI','Örnek ürün kuralları net; mühendislik soruları açık. Format örneği olarak kullanılabilir. Gerçek bir ürün için uygulamaya hazır olduğuna veya test edildiğine ilişkin iddia yok.','note')
body+=panel('Kod repo’su olmadan ilk prova: bu örneği çalıştır', '''<ol><li><b>Ayrı eğitim root’u aç.</b> Aşağıdaki kurulum yalnız prova içindir; gerçek ürün dosyalarının üzerine örnek spec kopyalama.</li></ol><div data-practice-setup></div><ol start="2"><li><button class="small" data-kit-download>Gömülü başlangıç ZIP’ini indir ↓</button> ZIP’i aç. İçindeki <code>pm-starter-kit/training-example/openspec/</code> klasöründe <code>specs/package-change</code> ve <code>changes/recover-package-change-result</code> vardır.</li><li>Dosya yöneticisinde <code>package-change</code> klasörünü prova root’undaki <code>openspec/specs/</code> içine; <code>recover-package-change-result</code> klasörünü <code>openspec/changes/</code> içine kopyala. Init ile üretilen skill’leri koru. Örneklerin tam içerikleri aşağıda.</li><li>Aynı prova root’unda aşağıdaki kontrolleri çalıştır. Beklenen: aktif listede tek örnek change ve validate sonucunda ana spec + change için hata yok. Bu örnek gerçek OpenSpec CLI ile strict kontrolden geçirilmiştir.</li></ol>'''+block('g-practice-check','TERMINAL · ayrı prova root’unda','openspec list\nopenspec show recover-package-change-result\nopenspec validate --all --strict')+'''<ol start="5"><li>Asistanı prova root’unda aç; plan review mesajını gönder. Açık design sorularını buldur, ürün/teknik karar ayrımını yap. Bu prova belge üretimi/incelemesi içindir; gerçek ürün kodu uygulanmış veya test edilmiş sayılmaz.</li><li>Ürünün için yeni root’ta aynı yöntemi gerçek kaynaklarla tekrarla; eğitim örneğini gerçek ürün kuralı gibi kullanma.</li></ol>''')
for i,(path,txt) in enumerate(case.items()): body+=panel(esc(path),block('g-case-'+str(i),'DOSYA · '+path,txt))
body+='''<h3>Delta nasıl seçilir?</h3><p>Başlangıçtaki <code>Gönderim sonucu</code> var: MODIFIED altında <b>tam yeni hâli</b> ve senaryoları yazılır. Aynı niyet / dönüş gereksinimleri yok: ADDED. Mevcut gereksinimi değiştirirken senaryo başlıklarını da koru; bu örnekte CLI kaybolan senaryoyu hata sayar. Değişmeyen diğer gereksinimleri delta içine kopyalama. Silme gerekiyorsa REMOVED ve gerekçe; capability’yi tamamen kaldırma özel işlemidir, atlasın kapanış bölümünde bulunur.</p><button class="small" data-case-download>Tam örnek dosyalarını indir ↓</button>'''
add('Aynı işin bütün dosyalarını gör.','Kısaltılmış slayt metni yerine başlangıç spec’i ve dört belge yan yana.',body,'Başlangıç → delta eşleşmesini gösterebiliyor ve açık tasarım kararları yüzünden apply için neden durulduğunu açıklayabiliyorsun.',source('writing-specs.md','Requirement ve delta biçimi'))
add('Planı sorgula; değişince hizala.','AI’ın düzgün yazması, ürün kararlarının doğru olduğu anlamına gelmez.', '''<div class="guide-grid"><div><h3>PM + domain review</h3><ol><li>Bu problem kimde, hangi kanıtla var?</li><li>Başarı, kapsam dışı ve açık kararlar görünür mü?</li><li>Her requirement gözlemlenebilir mi?</li><li>Belirsiz sonuç, kesin ret ve uygulanma ayrılıyor mu?</li><li>Kural ve süreler kaynaklı mı?</li></ol></div><div><h3>Mühendislik + QA review</h3><ol><li>Spec ile design aynı davranışı mı anlatıyor?</li><li>Eski mobil, eşzamanlılık, yetki ve dönüş kapsanıyor mu?</li><li>Her kritik senaryonun task/test karşılığı var mı?</li><li>Bağımlılıklar ve release sırası biliniyor mu?</li><li>Uygulama öncesi çözülmesi gereken soru kaldı mı?</li></ol></div></div><div data-review-prompt></div>'''+block('g-validate','TERMINAL · planlama root’unda','openspec validate recover-package-change-result --strict')+'''<p><b>Başarı:</b> CLI yapısal hata bildirmiyor. Bu, ürün kurallarının doğruluğunu ve kodun çalışmasını kanıtlamaz. Hata mesajındaki dosya, başlık veya eksik scenario’yu düzeltip yeniden çalıştır.</p>'''+call('İki update, iki farklı iş','Terminalde <code>openspec update</code> asistan yönergelerini yeniler. Sohbetteki plan update çağrısı mevcut change belgelerini değiştirir. Kod zaten uygulandıysa planı güncellemek kodu kendiliğinden uyarlamaz.','note')+'''<div data-update-prompt></div><p><b>Elle düzenleme de olur.</b> Markdown dosyasını değiştir, sonra asistana bu yeni hâli okutup proposal/spec/design/tasks çelişkilerini düzeltmesini iste. Yeni bağımsız sonuç için ayrı change aç; aynı değişiklikte öğrenilen kararları update et.</p>''','Format geçerli; kritik ürün/teknik kararlar çözülmüş; ekip planın aynı niyeti taşıdığını doğruluyor.',source('editing-changes.md','Düzenleme')+' · '+source('cli.md','Validate'))
add('Uygula; gerçek sonucu kanıtla.','Task kutusu, test sonucu ve ürün kabulü ayrı kayıtlardır.', '''<p>Planlama root’unda yalnız belgeleri değiştiren PM, kodu ilgili mühendislik sahibine devreder. Monorepo’da aynı root’ta devam edilebilir. Ayrı repolarda mobil/backend oturumları kendi implementation root’unda çalışır; ortak planın konumu ve sürümü her oturuma verilir.</p>
'''+block('g-handoff','ASİSTAN SOHBETİ · component root’unda mühendislik devri','Bu component root: <mobil veya backend mutlak yolu>.\nOrtak plan: <planning root>/openspec/changes/recover-package-change-result/.\nPlan sürümü: <commit>; bu component kaynak sürümü: <commit>.\nOrtak proposal/spec/design/tasks dosyalarını gerçekten oku.\nBu component’e ait işleri ve bağımlılıkları ayır. Başka repo’ya yazma.\nYerel OpenSpec change/reference gerekiyorsa ekip düzenine göre oluştur;\nortak ürün kurallarını çelişen bağımsız kopyaya dönüştürme.\nUygulama öncesi açık karar/erişim sorunu varsa raporla.\nSonuçta task → requirement → test kanıtı eşlemesini ver.')+'''<div data-apply-prompt></div><p>Apply, planın görevlerini uygulamaya geçirir. Kod ve test komutları ürünün stack’ine göre seçilir; OpenSpec ortak bir <code>npm test</code> zorunluluğu getirmez. Test yalnız okunmuşsa “çalıştırıldı” denmez.</p><table class="guide-table"><thead><tr><th>Kritik senaryo</th><th>Beklenen</th><th>Kanıt kaydı</th></tr></thead><tbody><tr><td>Backend kabul, yanıt kayıp</td><td>Belirsiz gösterim; ikinci talep yok.</td><td>Test adı, ortam, mobil/backend sürümü, gözlenen sonuç.</td></tr><tr><td>Eşzamanlı aynı niyet</td><td>En fazla bir talep.</td><td>Gerçek concurrency testi ve kayıt sayısı.</td></tr><tr><td>Kapanma → dönüş</td><td>Önceki niyetin durumu sorgulanır.</td><td>Mobil senaryo kaydı; yetkili yanıt.</td></tr><tr><td>Kesin ret / uygulanma</td><td>Doğru gerekçe / doğru sonuç.</td><td>İki ayrı kabul senaryosu.</td></tr><tr><td>Eski istemci / başka kullanıcı</td><td>Uyum ve yetki korunur.</td><td>Regression ve yetki testleri.</td></tr></tbody></table>'''+block('g-evidence','DOSYA · kabul kaydı örneği; sonuçları gerçekten doldur','Senaryo | Requirement | Ortam | Mobil/backend commit | Test/demo bağlantısı\nGözlenen sonuç | Durum: geçti / başarısız / çalıştırılmadı | Sahip | Tarih\n\nBir senaryonun geçmesi bütün senaryoların geçtiği anlamına gelmez.\nBaşarısız veya çalıştırılmayan kritik yolun kararı görünür kalır.')+panel('Verify kullanmalı mıyım?', '''<p>Expanded profilindeki verify, doküman ile uygulama uyumunu inceler. Faydalı ek review; test çalıştırmanın veya PM kabulünün yerine geçmez. Archive için OpenSpec’in zorunlu kilidi değildir. Açmak için terminalde <code>openspec config profile</code>, sonra <code>openspec update</code>. Üretilen verify skill/komutunu sohbetten kullan.</p>'''),'Kritik kabul senaryolarının gerçek kayıtları var; başarısız/çalıştırılmayanlar gizlenmiyor; ürün ve teknik sahipler sonucu incelemiş.',source('commands.md','Apply ve verify')+' · '+source('reviewing-changes.md','Kabul incelemesi'))
add('Sync, archive, release: üç ayrı sonuç.','Kapanıştan sonra yeni PM hangi davranışın referans olduğunu bulabilsin.', '''<div class="guide-map three"><div><b>SYNC</b><strong>Ana spec’i günceller</strong><span>Change delta’sı specs/ referansına işlenir.</span></div><div><b>ARCHIVE</b><strong>İşi geçmişe taşır</strong><span>Karar ve uygulama planı arşivde korunur.</span></div><div><b>RELEASE</b><strong>Ürünü yayımlar</strong><span>Backend deploy, mobil dağıtım, flag ve gözlem ayrı süreç.</span></div></div><div data-sync-prompt></div><p>Sync sonucu <code>openspec/specs/package-change/spec.md</code> dosyasını açıp tam yeni gereksinimleri incele. Gerekirse ayrı sync yapmadan archive akışı içinde sync teklifi gelir; yine sonucu kontrol et.</p><div data-archive-prompt></div>'''+block('g-close-check','TERMINAL · planlama root’unda','openspec list\nopenspec validate --all --strict\ngit status --short\ngit diff')+'''<p><b>Beklenen:</b> tamamlanan change aktif listeden çıkmış; <code>openspec/changes/archive/</code> altında tarihli kaydı var; ana spec beklenen yeni hâlde; Git diff istenen dosyaları gösteriyor. <code>git diff</code> yalnız izlenen dosyaları gösterir; yeni/untracked dosyaları ayrıca açıp incele.</p>
<h3>Ekiple nasıl paylaşılır?</h3><p>Planlama repo’sunda bağlam + change + spec dosyalarını ekipçe kullanılan branch/PR akışıyla paylaş. Component PR’ları ortak change kimliğine ve plan sürümüne bağlansın. Biri davranışı değiştirince kaynağı ve kabul kaydı da güncellensin. Git’e yazmak veya archive etmek canlıya çıkmak değildir.</p>'''+block('g-resume','ASİSTAN SOHBETİ · yarın yeni oturumda','Planlama root: <mutlak yol>. Önce docs/context/README.md ve sources.md oku.\nSonra openspec list ile aktif change’leri göster.\nDevam edeceğimiz change: <kimlik>; varsa proposal/spec/design/tasks oku.\nSon kaynak sürümleriyle değişen/eskimiş bağlamı raporla.\nTamamlanan, kalan ve açık kararları özetle; sonraki somut adımı öner.\nKaynak okumadan eski sohbetten ürün kuralı varsayma.')+'''<p>Yeni işe geçerken değişen bağlamı refresh et. Her küçük metin düzeltmesine dört belge açmak gerekmeyebilir; ekip için kalıcı davranış kararı veya riskli değişiklik varsa bu düzenin maliyeti karşılığını verir.</p>''','Ana spec, arşiv ve paylaşım kayıtları kontrol edilmiş; release durumu ayrı belirtilmiş; yeni sohbet işi yeniden bulabiliyor.',source('commands.md','Sync ve archive')+' · '+source('writing-specs.md','Ana spec'))
add('Takıldığında: belirti → teşhis → çözüm.','Hata mesajını değiştirmeden, hangi adımda çıktığını belirterek ilerle.', '''<div class="guide-troubles">
'''+panel('node/npm bulunamadı veya sürüm eski', '<p>Terminali yeniden aç; sürümleri tekrar kontrol et. Aktif Node yöneticin varsa desteklenen sürümü seç. Yoksa ortam adımındaki kurulum rotasını izle. GUI uygulamasının terminali eski ortamı taşıyorsa uygulamayı yeniden aç.</p>'+jump(1,'Ortam adımı'))+panel('openspec bulunamadı', '<p>Kurulum başarılı mı? Home alternatifi kullandıysan PATH doğru mu? Yeni terminalde de çalışıyor mu? macOS/Linux: <code>command -v openspec</code>; Windows: <code>Get-Command openspec</code>. Birden fazla Node/CLI varsa beklenen executable’ı kullandığını kontrol et. Home prefix için açık executable yoluyla sürümü çalıştır; çalışırsa sorun PATH’tir.</p>'+jump(2,'Kurulum ve kalıcı PATH'))+panel('EACCES / permission denied / kurulum yetkisi', '<p>İzin hatası sistem global hedefinden geliyorsa kullanıcı home alternatifine geç. Mevcut Node yöneticisi varsa onun kurulumunu kullan. Kurum kısıtıysa BT’den izinli yöntem iste. Dosyalar doğru kullanıcıya mı ait kontrol et; hata mesajını ve kurulum yolunu paylaş.</p>'+jump(2,'Home alternatifi'))+panel('Ağ / proxy / sertifika / oturum erişimi', '<p>Hangi host/servis erişilemediğini hata çıktısından ayır: npm indirmesi, repo clone veya AI hesabı. Kurum proxy/sertifika ve repo yetkisini ilgili sahibiyle çöz. Başarısız indirme tamamlanmış kurulum sayılmaz; erişim düzeldikten sonra sürüm ve okuma kontrolünü tekrar yap.</p>')+panel('Skill görünmüyor / sohbet komutu tanınmıyor', '<p>Doğru root ve doğru tool ID ile init yaptın mı? Üretilen dosya var mı? Asistanı aynı projede yeniden aç. CLI güncellendiğinde projede <code>openspec update</code> çalıştır. Codex’te dolar skill adı, Claude’da iki noktalı slash, Cursor’da tireli slash kullanılır. Verify gibi expanded skill default core’da yok.</p>'+jump(4,'Skill kontrolü'))+panel('AI dosyayı okuyamıyor veya çok genel konuşuyor', '<p>Yerel checkout var mı? Asistanın o klasöre erişimi var mı? Repo URL’si/ChatGPT proje adı tek başına yerel erişim değildir. Mutlak yol ver, ilgili dosyanın bölümünü ve commit’i okut. Okuyamıyorsa eksport belgelerle çalışıp eksik kanıtı işaretle. Büyük repo’da tek akış ve küçük okuma rotası seç.</p>'+jump(5,'Kaynaklı inceleme'))+panel('Yanlış projede değişiklik üretti', '<p>Yeni kod üretimini durdur. Asistana CWD/root ve yazdığı dosyaları raporlat; istenmeyen dosyaları birlikte incele. İlgisiz çalışmayı silmeden doğru root’ta yeniden aç. Birden fazla store/global default varsa hedefi netleştir. Root’lar ve ürünler birbirine karışmasın.</p>'+jump(3,'Root seçimi'))+panel('Validate hata verdi', '<p>CLI çıktısındaki dosyayı aç: ADDED/MODIFIED bölümü doğru mu? <code>### Requirement:</code>, <code>#### Scenario:</code>, MUST/SHALL ve en az bir senaryo var mı? MODIFIED başlığı ana spec’teki requirement adıyla eşleşiyor mu? Tam yeni requirement yazılmış mı? Mevcut senaryoların başlıkları korunmuş mu? Düzelttikten sonra aynı validate komutunu tekrar çalıştır.</p>'+jump(8,'Tam dosya örneği'))+panel('Belgede “tamamlandı” ama test yok', '<p>Durumu “çalıştırılmadı” olarak düzelt. Hangi requirement için hangi test/ortam/sürüm gerektiğini QA/mühendislikle belirle. Format geçmesi ve task işaretlemek kabul kanıtı değildir. Kritik eksik doğrulamanın sahibi ve sonraki adımı görünür olsun.</p>'+jump(10,'Doğrulama'))+panel('Plan değişti; kod eski davranışta kaldı', '<p>Update planı değiştirir. Etkilenen design/tasks/spec ile uygulamayı yeniden hizala; ilgili root’ta apply ve regression doğrulaması yap. Sırf belgeler güncel diye iş tamamlandı sayılmaz.</p>'+jump(9,'Plan güncelleme'))+panel('Örnekteki komut sürümümde yok', '<p><code>openspec --version</code> ve <code>openspec --help</code> çıktısını al. Core yolu tercih et. Beta store/workset/context komutlarını ilk işin ön koşulu yapma. Kurulu sürüm desteklemiyorsa ayrı planlama repo’su ve açık dosya referanslarıyla ilerle. Asistan yönergeleri ile CLI sürümü farklıysa projede update ile yenile.</p>')+'''</div>'''+block('g-support','ASİSTAN SOHBETİ · teşhis için doldur','OS ve terminal: <...>\nNode/npm/OpenSpec sürümleri: <...>\nAsistan ve proje root: <...>\nÇalıştırdığım tam komut veya sohbet mesajı: <...>\nHata çıktısı: <kişisel/secret bilgileri çıkararak aynen>\nBeklenen: <...>; Gözlenen: <...>\nYaptığım kontroller: <...>\nÖnce kök nedeni ayır, sonra en küçük düzeltmeyi öner.\nBaşarı kontrolünü tekrar çalıştır; ilgisiz dosyaları değiştirme.'),'Sorunu doğru katmana bağlayabiliyor; çözümden sonra aynı başarı kontrolünü tekrarlayabiliyorsun.',source('troubleshooting.md','Sorun giderme'))
add('Terim sözlüğü ve komut kartı.','Anlaşılmayan terim varsa cümleyi ezberleme; burada işiyle ilişkilendir.', '''<label class="guide-search-label" for="glossarySearch">Terimde veya açıklamada ara</label><input type="search" id="glossarySearch" placeholder="Örn. prefix, delta, API"><div id="glossaryList"></div><h3>Günlük komut kartı</h3><div data-command-card></div><p>Terminal komutları shell’de, skill/slash çağrıları asistan sohbetinde. Başlangıç için core yeterli. İleri komutlar atlasın ilk bölümünde.</p><button class="small" data-atlas-jump="0">İleri iş akışı ve komutlar →</button>''','CLI/skill/context farkını ve validate/sync/archive farkını kendi cümlenle anlatabiliyorsun.',source('cli.md','CLI')+' · '+source('how-commands-work.md','Komutlar'))
add('Hissetme; yapabildiğini göster.','Sekiz soru + kendi domain’inde bir iş. Yanlış cevabın gerekçesi de burada.', '''<p>Her soruya cevap ver; sonra kontrol et. Amaç kelime ezberi değil, yanlış karar vermeyi önlemek.</p><form id="guideQuiz"></form><div class="inline-controls"><button class="action" id="gradeQuiz">Cevapları kontrol et</button><button class="small" id="resetQuiz">Sıfırla</button></div><p id="quizResult" class="guide-call" role="status">Henüz değerlendirilmedi.</p><h3>Asıl bitirme görevi: kendi ürününde tek iş</h3><p>Bir akış seç. Kaynak ve sürümleri kaydet. Bir gözlem, bir ürün kuralı, bir açık soru yaz. Kapsam dışını belirle. En az bir mutlu yol, bir hata yolu ve bir tekrar/dönüş senaryosuyla değişiklik planını hazırla. Mühendislik/QA ile kabul kanıtının nasıl üretileceğini bağla.</p>'''+block('g-graduation','DOSYA · doldurulacak bitirme / devir kartı','Ürün + akış + kullanıcı:\nPlanlama root / change kimliği / plan commit:\nMobil / backend kaynak sürümleri:\nKaynaklı mevcut davranış:\nOnaylı beklenen davranış + karar sahibi:\nKapsam dışı:\nAçık karar + sahibi + sonraki adım:\nProposal/spec/design/tasks yolu:\nKritik senaryolar + test/demo sahibi:\nKabul kaydı: geçti / başarısız / çalıştırılmadı:\nSync / archive kontrolü:\nRelease durumu (ayrı):')+call('Bitiş ölçütü','Soruların doğru gerekçelerini açıklıyor ve kendi işinin kartını gerçek kaynaklarla doldurabiliyorsan bağımsız başlangıç yapabilirsin. Quiz sonucu, gerçek kurulum veya uygulama başarısını otomatik ölçmez.')+'''<p>Bu kartı doldurmak için eğitmene ihtiyaç yok; ürünün bilinmeyen kararlarında ilgili sahibine ihtiyaç var. OpenSpec karar sahibinin yerine karar vermez.</p>''','Bitirme kartı gerçek bir iş için dolu; eksikler sahibine bağlı; plan/kabul/release ayrımını koruyorsun.')
# Original content for terminology and evaluation.
glossary=[
('OpenSpec','AI kod asistanıyla davranış gereksinimi ve değişiklik planını sürümlenen dosyalarda yönetme aracı.'),
('Terminal / shell','Komut yazdığın arayüz / o komutu yorumlayan program. macOS’ta çoğu kullanıcı zsh, Windows’ta PowerShell kullanır.'),
('CLI','Command-line interface: terminalden çalışan araç. openspec komutu bunun örneği.'),
('Node.js / npm','Node çalıştırma ortamı; npm paket kurucusu. Asistan veya domain paketi değildir.'),
('Global / user / project','Global CLI her klasörden çağrılabilir; user ayar/skill kullanıcıya aittir; project bağlam/spec o ürüne aittir.'),
('Home / ~ / $HOME','Kullanıcı ana klasörü. ~ ve $HOME Unix shell kısaltmaları; PowerShell’de $HOME kullanıcı klasörünü verir.'),
('Prefix','npm kurulumunun üst hedef dizini. Unix’te komutlar genelde prefix/bin; Windows’ta prefix altında.'),
('PATH','Shell’in executable aradığı dizin listesi. Paket kurulmuş olsa da PATH eksikse komut bulunamayabilir.'),
('Executable','İşletim sisteminin çalıştırdığı program veya komut dosyası. Hangi kopyanın çağrıldığı önemlidir.'),
('Root / CWD / mutlak yol','Root projenin ana klasörü; CWD mevcut çalışma dizini. Mutlak yol konumu tam belirtir; göreli yol CWD’ye bağlıdır.'),
('Repo / checkout / clone','Repo sürümlenen proje; checkout bilgisayarındaki çalışma kopyası; clone uzaktaki repo’dan bu kopyayı oluşturur.'),
('Branch / commit / diff / PR','Branch çalışma hattı; commit kayıtlı sürüm; diff dosya farkı; PR ekip incelemesine sunulan değişiklik.'),
('Domain','Ürünün problem alanı ve iş kuralları. Örnek: ödeme, abonelik, kimlik doğrulama.'),
('Context / bağlam','AI’ın işi doğru yorumlaması için ürün niyeti, kaynaklar, kurallar, sürümler ve kararlar.'),
('Skill / slash command','Asistanın belirli çalışma yöntemini çağırma yolu. Codex skill’i $openspec-…; diğer asistanlarda /opsx biçimleri.'),
('AGENTS.md','Asistana proje çalışma talimatı veren dosya. Mevcut talimatlar korunarak okuma protokolü eklenir.'),
('Schema / artifact / rules','Schema belge türleri ve bağımlılıklarını tanımlar; artifact bir çalışma belgesi; rules belgeye özel yönergeler.'),
('Proposal','Neden bu değişiklik, ne değişecek, kapsam ve etki. Ürün hedefinin başlangıç belgesi.'),
('Spec / requirement / scenario','Spec davranış sözleşmesi; requirement beklenen bir davranış; scenario belirli koşul ve gözlemlenebilir sonuç.'),
('Capability','Spec’lerin düzenlendiği davranış/yetenek alanı; bu örnekte package-change. Klasör adı ve proposal eşleşmelidir.'),
('Delta / ADDED / MODIFIED / REMOVED','Mevcut spec’e göre davranış farkı. Yeni gereksinim / tam yeni sürüm / gerekçeli kaldırma.'),
('GIVEN / WHEN / THEN','Başlangıç koşulu / olay / beklenen sonuç. Belirsiz “düzgün çalışır” yerine gözlemlenebilir sonuç yaz.'),
('MUST / SHALL / SHOULD / MAY','Zorunlu / zorunlu / öneri / isteğe bağlı. Ürün gereksiniminin bağlayıcılık dilini netleştirir.'),
('Design / tasks','Design teknik çözüm ve riskler; tasks uygulama ve doğrulama işlerinin listesi. Figma tasarımıyla aynı anlamda değil.'),
('Explore / propose / apply / update','Keşif / plan üretimi / uygulama / plan güncelleme. Terminaldeki openspec update asistan yönergelerini yeniler.'),
('Validate / verify / kabul','Validate formatı kontrol eder; verify belge-kod uyumunu inceler; kabul gözlenen ürün davranışına dayanır.'),
('Sync / archive','Sync deltayı ana spec’e işler; archive change’i geçmişe taşır. Ürünü yayımlamaz.'),
('API / endpoint / handler','Bileşenler arası sözleşme / çağrılan adres+işlem / backend’de isteği karşılayan kod.'),
('Timeout / retry / idempotency','Yanıt zamanında gelmedi / yeniden dene / aynı niyetin tekrarında ek iş etkisi oluşmaması. Timeout kesin ret değildir.'),
('operationKey / requestId','Bu vakada gönderimden önce oluşturulan niyet anahtarı / sunucu talep kimliği. Yanıtta dönen ID, yanıt kaybında tek başına yeterli olmayabilir.'),
('Atomiklik / concurrency','İşin bölünmez tamamlanması / aynı anda gerçekleşen işler. Tek talep sözü eşzamanlı tekrar testini gerektirir.'),
('Deploy / release / flag / rollback','Backend dağıtımı / kullanıcıya sürüm sunma / davranışı açan ayar / önceki güvenli hâle dönüş.'),
('Store / workset / beta','Store paylaşılan plan konumu; workset kişisel çalışma klasörleri grubu. Beta seçenekler ilk iş için zorunlu değil; kod erişimi otomatik oluşmaz.'),
('Kaynak / sürüm / kanıt','İddiayı nerede gördüğün / hangi kayıtlı hâlini incelediğin / davranışı destekleyen gözlem veya gerçek test sonucu.')]
quiz=[
('CLI home’a kuruldu. Ürün A ve B’nin bağlamı nereye gider?',['Tek bir global context’e.','Her ürünün kendi planlama root’una.','Generated skill dosyasının içine.'],1,'Global kurulum yöntemi ortaklaştırır. Ürün bağlamı/spec farklı root’larda kalır.',2),
('Backend talebi kabul etti, mobil yanıt alamadı. Kesin olan ne?',['Talep başarısızdır.','Paket uygulanmıştır.','Mobil sonuçtan emin değildir; sunucu durumu doğrulanmalı.'],2,'Yanıt kaybı istemci bilgisidir. Kabul ve uygulanma ayrı durumlar; güvenilir kaynaktan kontrol gerekir.',5),
('config.yaml’a bir dosya yolu yazdın. Bu neyi garantiler?',['Dosyanın bütün içeriği okundu.','Sadece bir okuma referansı verildi; okuma kanıtı ayrıca gerekir.','Kaynak günceldir.'],1,'Path görünmesi, dosyanın okunması ve sürümünün doğru olması aynı şey değil.',6),
('Mevcut Gönderim sonucu requirement’ını değiştiriyorsun. Delta?',['MODIFIED altında tam yeni requirement ve senaryoları.','ADDED altında yalnız değişen cümle.','Ana spec’i sil ve archive et.'],0,'MODIFIED aynı adlı mevcut gereksinimi tam yeni hâliyle değiştirir; kopuk tek cümle yeterli değildir. Mevcut senaryo adlarını koru; bu örnekte gerçek CLI doğrulaması ad değişimini eksik senaryo saydı.',8),
('Validate geçti. Ne kanıtlandı?',['Tüm mobil/backend testleri geçti.','Ürün yayımlandı.','Yapısal/format kontrolü geçti.'],2,'Test ve ürün kabulü gerçek davranış kanıtı gerektirir. Format kontrolü bunları çalıştırmaz.',9),
('Sohbette update ile plan değişti, daha önce kod uygulanmıştı. Sonraki adım?',['Kod kendiliğinden değişti.','Etkilenen kod/tasks’i apply ve test ile yeniden hizala.','Hemen archive et.'],1,'Plan düzenlemesi uygulanmış kodu kendiliğinden değiştirmez.',9),
('QA kritik dönüş senaryosunu çalıştırmadı. Durum?',['Çalıştırılmadı; sahibi ve sonraki adımı görünür.','Tasks işaretliyse geçti.','AI olumlu yazdıysa geçti.'],0,'Kanıt yoksa passed yok. İncelenmiş test dosyası çalıştırılmış test değildir.',10),
('Archive başarılı. Canlı release durumu?',['Bütün kullanıcılar yeni davranışta.','Backend deploy oldu; mobile gerek yok.','Ayrı deploy/app release/flag kanıtıyla belirlenir.'],2,'Archive dosya geçmişini yönetir. Canlı yayın ve sürüm uyumu ayrı süreçler.',11)]
css='''
/* Self-contained learner runbook, added after the instructional audit. */
.tools #guideBtn{background:#244fd6;color:white;font-weight:650}.tools #workshopBtn{background:#edf2ff;color:#244fd6;border:1px solid #8da8f3}
#guide{width:min(1250px,96vw);max-width:96vw;height:min(900px,94svh);max-height:94svh;padding:0;overflow:hidden}
#guide .modal-head{padding:16px 24px;background:white}#guide .modal-head h2{font-size:25px}
.guide-layout{display:grid;grid-template-columns:245px minmax(0,1fr);height:calc(100% - 69px);min-height:0}
.guide-sidebar{padding:20px 16px;background:#edf2ff;border-right:1px solid var(--line);overflow-y:auto;min-width:0}
.guide-sidebar p{font-size:12px}.guide-sidebar label{font-size:12px;display:block;color:var(--muted);margin-bottom:12px}
.guide-sidebar select,.guide-sidebar input{width:100%;padding:9px;background:white;color:var(--ink);border:1px solid var(--line);border-radius:4px;margin-top:5px;min-width:0;font-size:13px}
#guideMenu{display:grid;gap:3px;margin-top:18px}#guideMenu button{background:transparent;color:var(--ink);font-size:13px;line-height:1.4;padding:10px;text-align:left;border-radius:4px;display:flex;gap:10px}#guideMenu button span{font:12px var(--mono);color:var(--muted);padding-top:2px}#guideMenu button.active{background:#244fd6;color:white}#guideMenu button.active span{color:white}#guideMenu button:hover:not(.active){background:#dbe5ff}
.guide-article{padding:30px 36px 24px;overflow-y:auto;min-width:0;background:var(--paper);font-size:15px;line-height:1.55}
.guide-article h2{font-size:38px;line-height:1.12;margin:8px 0 12px}.guide-article .guide-sub{font-size:18px;color:var(--muted);margin-bottom:27px}.guide-article h3{margin:23px 0 12px;font-size:18px}.guide-article li{margin-bottom:8px}.guide-article p,.guide-article td{overflow-wrap:anywhere}.guide-article ol{padding-left:23px}.guide-article button{margin:4px 0}.guide-topline{font:11px var(--mono);color:var(--blue);letter-spacing:.06em}
.guide-grid{display:grid;grid-template-columns:1fr 1fr;gap:27px}.guide-grid>div{min-width:0}.guide-grid h3:first-child{margin-top:0}.guide-map{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin:20px 0 26px;border:1px solid var(--line);background:white}.guide-map.three{grid-template-columns:repeat(3,minmax(0,1fr))}.guide-map>div{padding:18px 16px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:9px;min-width:0}.guide-map>div:last-child{border:0}.guide-map b{font:22px Georgia,serif;color:var(--blue)}.guide-map strong{font-size:15px}.guide-map span{font-size:12px;color:var(--muted);line-height:1.5;overflow-wrap:anywhere}
.guide-code{background:#142747;color:#f7f9fd;margin:18px 0;border:1px solid #647591;border-radius:5px;overflow:hidden}.guide-code-head{display:flex;gap:12px;justify-content:space-between;align-items:center;padding:9px 15px;border-bottom:1px solid #647591;font:11px var(--mono);color:#c4d1e6}.guide-code-head span{overflow-wrap:anywhere}.guide-code .small{color:#f7f9fd;font:12px var(--sans);padding:7px 11px;flex-shrink:0;margin:0}.guide-code pre{font-size:13px;line-height:1.8;padding:17px 19px;white-space:pre-wrap;overflow-wrap:anywhere;color:inherit}
.guide-call{border:1px solid var(--line);border-left:4px solid var(--blue);padding:16px 19px;background:#edf2ff;margin:20px 0;line-height:1.55}.guide-call strong{display:block;margin-bottom:6px}.guide-call.note{background:#fff1d6;border-left-color:var(--amber)}.guide-call.ok{background:#e3f2eb;border-left-color:#176146}.guide-legend{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.guide-legend span{font:11px var(--mono);padding:9px 11px;background:white;border:1px solid var(--line)}
.guide-details{border:1px solid var(--line);background:white;border-radius:4px;margin:14px 0}.guide-details>summary{padding:14px 16px;cursor:pointer;font-size:14px;overflow-wrap:anywhere;font-weight:650}.guide-details>div{padding:0 19px 16px}.guide-details>div p:last-child{margin-bottom:0}.guide-details .guide-code{margin-bottom:0}
.guide-table{border-collapse:collapse;width:100%;margin:18px 0;font-size:13px;table-layout:fixed}.guide-table th,.guide-table td{padding:12px 10px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line);line-height:1.6}.guide-table th{background:#edf2ff}.guide-table tr td:first-child{font-weight:600}
.guide-gate{margin-top:30px;border-top:2px solid var(--blue);padding-top:20px}.guide-gate .guide-topline{display:block;margin-bottom:9px}.guide-navigation{display:flex;justify-content:space-between;gap:14px;margin-top:21px;flex-wrap:wrap}.guide-sources{font-size:11px;color:var(--muted);margin-top:24px;line-height:1.8}.guide-search-label{display:block;font-size:13px}#glossarySearch{width:100%;padding:12px;margin:8px 0 15px;border:1px solid var(--line);background:white;color:var(--ink)}.glossary-item{border-top:1px solid var(--line);padding:14px 0}.glossary-item dt{font-weight:650;font-size:15px}.glossary-item dd{margin:6px 0 0;font-size:14px;color:var(--muted)}
.guide-question{padding:19px 20px;border:1px solid var(--line);background:white;margin:16px 0;min-width:0}.guide-question legend{font-weight:650;padding:0 6px}.guide-question label{display:flex;gap:10px;margin:10px 0;align-items:flex-start;font-size:14px;cursor:pointer}.guide-question input{margin-top:5px;accent-color:var(--blue);flex-shrink:0}.quiz-feedback{margin-top:15px;padding:13px;background:#edf2ff;font-size:13px}.quiz-feedback.wrong{background:#fff1d6}.guide-no-results{font-size:13px;margin-top:12px;color:var(--muted)}
.guide-print-only{display:none}
@media(min-width:761px) and (max-width:1300px){.brand span{display:none}.tools{gap:2px}.tools button{font-size:12px;padding:10px 8px}header.chrome{padding:0 3%}}
@media(max-width:760px){header.chrome{height:auto;min-height:90px;flex-wrap:wrap;gap:7px;padding:12px 5%}.tools{width:100%;gap:3px;justify-content:space-between}.tools button{font-size:11px;padding:9px 7px}.tools #workshopBtn{display:none}.stage{min-height:calc(100svh - 172px)}#guide{width:100vw;max-width:100vw;height:100svh;max-height:100svh;border:0;border-radius:0}#guide .modal-head{padding:13px 16px}#guide .modal-head h2{font-size:22px}.guide-layout{display:flex;flex-direction:column;height:calc(100% - 65px)}.guide-sidebar{flex-shrink:0;border-right:0;border-bottom:1px solid var(--line);padding:11px 16px;overflow:visible;display:grid;grid-template-columns:1fr 1fr;gap:8px}.guide-sidebar>p,.guide-sidebar>button{display:none}.guide-sidebar label{margin:0;min-width:0}.guide-sidebar label[for="guideSearch"]{grid-column:1/3}#guideSearch{margin:3px 0 0;padding:7px}#guideMenu{display:flex;overflow-x:auto;grid-column:1/3;margin:0;padding:3px 0;gap:4px}#guideMenu button{white-space:nowrap;padding:7px 9px;font-size:12px}#guideMenu button span{font-size:11px}.guide-article{padding:23px 19px;flex:1;min-height:0}.guide-article h2{font-size:31px}.guide-article .guide-sub{font-size:16px}.guide-grid{grid-template-columns:1fr;gap:12px}.guide-map,.guide-map.three{grid-template-columns:1fr 1fr}.guide-map>div{border-bottom:1px solid var(--line);padding:14px}.guide-map>div:nth-child(2n){border-right:0}.guide-map>div:last-child{border-bottom:0}.guide-map strong{font-size:14px}.guide-code pre{font-size:12px;padding:14px}.guide-code-head{font-size:10px;padding:8px 12px}.guide-table{font-size:11px}.guide-table th,.guide-table td{padding:9px 5px}.guide-question{padding:15px 12px}.guide-details>div{padding:0 13px 13px}}
@media print{body.guide-print .stage,body.guide-print header.chrome,body.guide-print footer.chrome,body.guide-print dialog{display:none!important}body.guide-print .guide-print-only{display:block;font:12px var(--sans);color:#17243e}body.guide-print .guide-print-only article{break-before:page;padding:12mm}body.guide-print .guide-print-only article:first-child{break-before:auto}.guide-print-only .guide-map{grid-template-columns:repeat(4,1fr)}.guide-print-only .guide-map.three{grid-template-columns:repeat(3,1fr)}.guide-print-only h2{font-size:28px}.guide-print-only h3{margin-top:20px}.guide-print-only .guide-code{background:white;color:#17243e;border-color:#c3ccdb;break-inside:auto}.guide-print-only .guide-code-head{color:#4b5b73;border-color:#c3ccdb}.guide-print-only .guide-code pre{font-size:10px;color:#17243e}.guide-print-only button{display:none!important}.guide-print-only .guide-details{break-inside:auto}.guide-print-only .guide-call{break-inside:avoid}.guide-print-only .guide-gate{margin-top:15px}.guide-print-only .guide-sources{font-size:9px}}
'''
